import re,glob,os
tbl={}
for line in open('draft/numerals.md'):
    m=re.match(r'\|\s*(\d+)\s*\|\s*(.+?)\s*\|',line)
    if m and m.group(1).isdigit(): tbl[m.group(1)]=m.group(2)
used=set()
for f in glob.glob('draft/0*.md')+glob.glob('draft/1*.md')+glob.glob('figures/*.md'):
    t=open(f).read()
    for n in re.findall(r'\b(\d{2})\b',t):
        if n in tbl: used.add(n)
    for bad in ['TODO','TBD','[ ]','placeholder','—','XXX']:
        if bad in t: print('MARKER',f,bad)
print('table not used:',sorted(set(tbl)-used))
